draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // grapes
  ctx.fillStyle = 'purple';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 50, H / 2 + Math.cos(t + i) * 20, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // stem
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 - 50);
  ctx.lineTo(W / 2, H / 2 - 100 + Math.sin(t) * 20);
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W / 2 - 20, H / 2 - 120, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 20, H / 2 - 120, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
